-- Invitații de nuntă, etapa a doua (Daniel, 27.11.2026): modelele trec din cod în baza de date, ca să se scrie din Admin.
-- Tabel nou; „shop_order” și restul nu se schimbă. Modelul Maramureș intră ca ciornă (fără ZIP): se publică din Admin după ce
-- se urcă fișierul. Bucovina nu exista în cod, deci nu e adăugată.
CREATE TABLE IF NOT EXISTS "shop_product" (
  "id" text PRIMARY KEY NOT NULL,
  "slug" text NOT NULL,
  "region" text DEFAULT '' NOT NULL,
  "status" text DEFAULT 'draft' NOT NULL,
  "texts" jsonb DEFAULT '{}'::jsonb NOT NULL,
  "languages" jsonb DEFAULT '[]'::jsonb NOT NULL,
  "formats" jsonb DEFAULT '[]'::jsonb NOT NULL,
  "price_ron" integer DEFAULT 4500 NOT NULL,
  "price_eur" integer DEFAULT 900 NOT NULL,
  "images" jsonb DEFAULT '[]'::jsonb NOT NULL,
  "zip_key" text,
  "zip_name" text,
  "zip_size" integer,
  "zip_files" integer,
  "zip_version" integer DEFAULT 0 NOT NULL,
  "zip_updated_at" timestamp,
  "sort" integer DEFAULT 0 NOT NULL,
  "created_at" timestamp DEFAULT now() NOT NULL,
  "updated_at" timestamp DEFAULT now() NOT NULL,
  "published_at" timestamp
);--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "shop_product_slug_idx" ON "shop_product" ("slug");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "shop_product_status_idx" ON "shop_product" ("status","sort");--> statement-breakpoint
INSERT INTO "shop_product" ("id", "slug", "region", "status", "texts", "languages", "formats", "price_ron", "price_eur", "images", "sort")
VALUES ('maramures', 'maramures', 'Maramureș', 'draft', '{"ro":{"name":"Maramureș","title":"Invitație de nuntă Maramureș, cu motive populare","tagline":"Poarta maramureșeană, biserica de lemn și cusăturile în roșu și negru.","description":"Motivele sunt desenate după cusăturile vechi pe grilă: romburi, stele cu opt colțuri, colții lupului și funia. Sus stă poarta maramureșeană cu rozeta soarelui sau biserica de lemn cu turla înaltă. Două variante: roșu-negru pe crem și întunecată, cu benzi ca la zadie și accente aurii.","metaTitle":"Invitație de nuntă tradițională Maramureș, PDF editabil","metaDescription":"Invitație de nuntă cu motive maramureșene: poarta cu rozeta, biserica de lemn și cusături în roșu și negru. PDF editabil și de printat, 5×7 și A5, în 7 limbi.","colors":"Varianta roșu-negru pe crem; Varianta întunecată, cu accente aurii"},"en-GB":{"name":"Maramureș","title":"Maramureș wedding invitation with Romanian folk motifs","tagline":"The carved Maramureș gate, the wooden church and red-and-black cross-stitch.","description":"The motifs follow old counted-thread stitches: diamonds, eight-pointed stars, the wolf’s teeth and the twisted rope. At the top stands the Maramureș gate with its sun rosette, or the wooden church with its tall spire. Two versions: red and black on cream, and a dark one with apron-like stripes and golden accents.","metaTitle":"Romanian folk wedding invitation Maramureș, editable PDF","metaDescription":"Traditional Romanian wedding invitation template from Maramureș: carved gate, wooden church and red-and-black cross-stitch. Editable and print PDF, 5×7 and A5, 7 languages.","colors":"Red and black on cream; Dark version with golden accents"},"fr":{"name":"Maramureș","title":"Faire-part de mariage Maramureș, motifs populaires roumains","tagline":"Le portail du Maramureș, l’église en bois et le point de croix rouge et noir.","description":"Les motifs suivent les anciennes broderies au point compté : losanges, étoiles à huit branches, dents de loup et corde torsadée. En haut se dresse le portail du Maramureș avec sa rosace solaire, ou l’église en bois au clocher élancé. Deux variantes : rouge et noir sur crème, et une sombre aux bandes de tablier et accents dorés.","metaTitle":"Faire-part de mariage roumain Maramureș, PDF modifiable","metaDescription":"Faire-part de mariage traditionnel roumain du Maramureș : portail sculpté, église en bois et point de croix rouge et noir. PDF modifiable et à imprimer, 5×7 et A5, 7 langues.","colors":"Rouge et noir sur crème; Variante sombre aux accents dorés"},"es":{"name":"Maramureș","title":"Invitación de boda Maramureș, con motivos populares rumanos","tagline":"El portón de Maramureș, la iglesia de madera y el punto de cruz rojo y negro.","description":"Los motivos siguen los antiguos bordados de hilo contado: rombos, estrellas de ocho puntas, dientes de lobo y la cuerda trenzada. Arriba se alza el portón de Maramureș con su roseta solar o la iglesia de madera con su alta torre. Dos variantes: rojo y negro sobre crema, y una oscura con franjas de delantal y detalles dorados.","metaTitle":"Invitación de boda tradicional rumana Maramureș, PDF editable","metaDescription":"Invitación de boda tradicional rumana de Maramureș: portón tallado, iglesia de madera y punto de cruz rojo y negro. PDF editable y para imprimir, 5×7 y A5, 7 idiomas.","colors":"Rojo y negro sobre crema; Variante oscura con detalles dorados"},"nl":{"name":"Maramureș","title":"Trouwkaart Maramureș met Roemeense volksmotieven","tagline":"De poort van Maramureș, de houten kerk en rood-zwart kruissteekwerk.","description":"De motieven volgen oud telwerkborduursel: ruiten, achtpuntige sterren, wolfstanden en het gedraaide touw. Bovenaan staat de poort van Maramureș met de zonnerozet, of de houten kerk met de hoge toren. Twee varianten: rood en zwart op crème, en een donkere met schortbanden en gouden accenten.","metaTitle":"Roemeense trouwkaart Maramureș, invulbare pdf","metaDescription":"Traditionele Roemeense trouwkaart uit Maramureș: gesneden poort, houten kerk en rood-zwart kruissteekwerk. Invulbare en print-pdf, 5×7 en A5, 7 talen.","colors":"Rood en zwart op crème; Donkere variant met gouden accenten"},"de":{"name":"Maramureș","title":"Hochzeitseinladung Maramureș mit rumänischen Volksmotiven","tagline":"Das Tor der Maramureș, die Holzkirche und rot-schwarzer Kreuzstich.","description":"Die Motive folgen alten Zählstickereien: Rauten, achtzackige Sterne, Wolfszähne und das gedrehte Seil. Oben steht das Maramureș-Tor mit der Sonnenrosette oder die Holzkirche mit dem hohen Turm. Zwei Varianten: Rot und Schwarz auf Creme sowie eine dunkle mit Schürzenstreifen und goldenen Akzenten.","metaTitle":"Rumänische Hochzeitseinladung Maramureș, ausfüllbares PDF","metaDescription":"Traditionelle rumänische Hochzeitseinladung aus der Maramureș: geschnitztes Tor, Holzkirche und rot-schwarzer Kreuzstich. Ausfüllbares und Druck-PDF, 5×7 und A5, 7 Sprachen.","colors":"Rot und Schwarz auf Creme; Dunkle Variante mit goldenen Akzenten"},"it":{"name":"Maramureș","title":"Invito di nozze Maramureș con motivi popolari romeni","tagline":"Il portale del Maramureș, la chiesa di legno e il punto croce rosso e nero.","description":"I motivi seguono gli antichi ricami a fili contati: rombi, stelle a otto punte, denti di lupo e la corda ritorta. In alto c’è il portale del Maramureș con la rosetta del sole, oppure la chiesa di legno con l’alto campanile. Due varianti: rosso e nero su crema, e una scura con bande da grembiule e dettagli dorati.","metaTitle":"Invito nozze tradizionale romeno Maramureș, PDF modificabile","metaDescription":"Invito di nozze tradizionale romeno del Maramureș: portale intagliato, chiesa di legno e punto croce rosso e nero. PDF modificabile e da stampare, 5×7 e A5, 7 lingue.","colors":"Rosso e nero su crema; Variante scura con dettagli dorati"},"hu":{"name":"Máramaros","title":"Máramarosi esküvői meghívó román népi motívumokkal","tagline":"A máramarosi kapu, a fatemplom és a piros-fekete keresztszemes minta.","description":"A motívumok a régi, szálszámolásos hímzéseket követik: rombuszok, nyolcágú csillagok, farkasfog és sodrott kötél. Felül a máramarosi kapu áll a napozettával, vagy a fatemplom a magas tornyával. Két változat: piros és fekete krémszínen, valamint egy sötét, kötényszerű sávokkal és arany díszekkel.","metaTitle":"Hagyományos máramarosi esküvői meghívó, kitölthető PDF","metaDescription":"Hagyományos esküvői meghívó máramarosi motívumokkal: faragott kapu, fatemplom és piros-fekete keresztszemes minta. Kitölthető és nyomtatható PDF, 5×7 és A5, 7 nyelven.","colors":"Piros és fekete krémszínen; Sötét változat arany díszekkel"},"he":{"name":"מרמורש","title":"הזמנה לחתונה מרמורש עם מוטיבים עממיים רומניים","tagline":"השער של מרמורש, כנסיית העץ ורקמת הצלב באדום ושחור.","description":"המוטיבים עוקבים אחרי רקמות עתיקות בספירת חוטים: מעוינים, כוכבים בעלי שמונה קצוות, שיני הזאב והחבל השזור. למעלה ניצב שער מרמורש עם רוזטת השמש, או כנסיית העץ עם הצריח הגבוה. שתי גרסאות: אדום ושחור על רקע שמנת, וגרסה כהה עם פסים כמו בסינר ונגיעות זהב.","metaTitle":"הזמנה לחתונה רומנית מסורתית מרמורש, PDF למילוי","metaDescription":"הזמנה לחתונה בסגנון רומני מסורתי ממרמורש: שער מגולף, כנסיית עץ ורקמת צלב באדום ושחור. PDF למילוי ולהדפסה, ‎5×7 ו-A5, ב-7 שפות.","colors":"אדום ושחור על רקע שמנת; גרסה כהה עם נגיעות זהב"},"pt":{"name":"Maramureș","title":"Convite de casamento Maramureș com motivos populares romenos","tagline":"O portão de Maramureș, a igreja de madeira e o ponto de cruz vermelho e preto.","description":"Os motivos seguem os antigos bordados de fio contado: losangos, estrelas de oito pontas, dentes de lobo e a corda torcida. Em cima ergue-se o portão de Maramureș com a roseta solar, ou a igreja de madeira com a torre alta. Duas variantes: vermelho e preto sobre creme, e uma escura com faixas de avental e detalhes dourados.","metaTitle":"Convite de casamento romeno Maramureș, PDF editável","metaDescription":"Convite de casamento tradicional romeno de Maramureș: portão esculpido, igreja de madeira e ponto de cruz vermelho e preto. PDF editável e para imprimir, 5×7 e A5, 7 línguas.","colors":"Vermelho e preto sobre creme; Variante escura com detalhes dourados"},"el":{"name":"Μαραμούρες","title":"Πρόσκληση γάμου Μαραμούρες με ρουμανικά λαϊκά μοτίβα","tagline":"Η πύλη του Μαραμούρες, η ξύλινη εκκλησία και η κόκκινη-μαύρη σταυροβελονιά.","description":"Τα μοτίβα ακολουθούν παλιά κεντήματα μετρητής κλωστής: ρόμβους, οκτάκτινα αστέρια, δόντια του λύκου και το στριφτό σχοινί. Πάνω στέκει η πύλη του Μαραμούρες με τη ροζέτα του ήλιου ή η ξύλινη εκκλησία με το ψηλό καμπαναριό. Δύο εκδοχές: κόκκινο και μαύρο σε κρεμ, και μια σκούρα με λωρίδες ποδιάς και χρυσές λεπτομέρειες.","metaTitle":"Ρουμανική πρόσκληση γάμου Μαραμούρες, επεξεργάσιμο PDF","metaDescription":"Παραδοσιακή ρουμανική πρόσκληση γάμου από το Μαραμούρες: σκαλιστή πύλη, ξύλινη εκκλησία και κόκκινο-μαύρο σταυροβελονιά. Επεξεργάσιμο PDF και PDF εκτύπωσης, 5×7 και A5, 7 γλώσσες.","colors":"Κόκκινο και μαύρο σε κρεμ; Σκούρα εκδοχή με χρυσές λεπτομέρειες"},"sv":{"name":"Maramureș","title":"Bröllopsinbjudan Maramureș med rumänska folkmotiv","tagline":"Porten från Maramureș, träkyrkan och korsstygn i rött och svart.","description":"Motiven följer gamla räknade broderier: romber, åttauddiga stjärnor, vargtänder och det tvinnade repet. Överst står Maramureș-porten med solrosetten, eller träkyrkan med det höga tornet. Två varianter: rött och svart på krämvitt, och en mörk med förklädesränder och gyllene detaljer.","metaTitle":"Rumänsk bröllopsinbjudan Maramureș, ifyllbar pdf","metaDescription":"Traditionell rumänsk bröllopsinbjudan från Maramureș: snidad port, träkyrka och korsstygn i rött och svart. Ifyllbar pdf och utskrifts-pdf, 5×7 och A5, 7 språk.","colors":"Rött och svart på krämvitt; Mörk variant med gyllene detaljer"},"da":{"name":"Maramureș","title":"Bryllupsinvitation Maramureș med rumænske folkemotiver","tagline":"Porten fra Maramureș, trækirken og korssting i rødt og sort.","description":"Motiverne følger gamle tællebroderier: ruder, ottetakkede stjerner, ulvetænder og det snoede reb. Øverst står Maramureș-porten med solrosetten eller trækirken med det høje tårn. To varianter: rødt og sort på creme og en mørk med forklædestriber og gyldne detaljer.","metaTitle":"Rumænsk bryllupsinvitation Maramureș, udfyldbar pdf","metaDescription":"Traditionel rumænsk bryllupsinvitation fra Maramureș: udskåret port, trækirke og korssting i rødt og sort. Udfyldbar pdf og pdf til print, 5×7 og A5, 7 sprog.","colors":"Rødt og sort på creme; Mørk variant med gyldne detaljer"},"nb":{"name":"Maramureș","title":"Bryllupsinvitasjon Maramureș med rumenske folkemotiver","tagline":"Porten fra Maramureș, trekirken og korssting i rødt og svart.","description":"Motivene følger gamle tellebroderier: ruter, åttetaggede stjerner, ulvetenner og det tvunnede tauet. Øverst står Maramureș-porten med solrosetten, eller trekirken med det høye tårnet. To varianter: rødt og svart på krem, og en mørk med forklestriper og gylne detaljer.","metaTitle":"Rumensk bryllupsinvitasjon Maramureș, utfyllbar pdf","metaDescription":"Tradisjonell rumensk bryllupsinvitasjon fra Maramureș: utskåret port, trekirke og korssting i rødt og svart. Utfyllbar pdf og pdf for utskrift, 5×7 og A5, 7 språk.","colors":"Rødt og svart på krem; Mørk variant med gylne detaljer"},"uk":{"name":"Марамуреш","title":"Весільне запрошення Марамуреш з румунськими народними мотивами","tagline":"Марамуреська брама, дерев’яна церква й червоно-чорна вишивка хрестиком.","description":"Мотиви повторюють давню лічильну вишивку: ромби, восьмипроменеві зірки, вовчі зуби й кручену мотузку. Угорі стоїть марамуреська брама з сонячною розетою або дерев’яна церква з високою вежею. Два варіанти: червоне й чорне на кремовому та темний, зі смугами, як на запасці, і золотими акцентами.","metaTitle":"Румунське весільне запрошення Марамуреш, PDF для заповнення","metaDescription":"Традиційне румунське весільне запрошення з Марамурешу: різьблена брама, дерев’яна церква й червоно-чорна вишивка хрестиком. PDF для заповнення й друку, 5×7 і A5, 7 мов.","colors":"Червоне й чорне на кремовому; Темний варіант із золотими акцентами"},"sr":{"name":"Maramureš","title":"Pozivnica za venčanje Maramureš sa rumunskim narodnim motivima","tagline":"Maramureška kapija, drvena crkva i crveno-crni vez krstićima.","description":"Motivi prate stare vezove po brojanim nitima: rombove, osmokrake zvezde, vučje zube i uvijeno uže. Gore stoji maramureška kapija sa sunčevom rozetom ili drvena crkva sa visokim tornjem. Dve varijante: crveno i crno na krem podlozi i tamna, sa prugama kao na pregači i zlatnim detaljima.","metaTitle":"Rumunska pozivnica za venčanje Maramureš, PDF za popunjavanje","metaDescription":"Tradicionalna rumunska pozivnica za venčanje iz Maramureša: rezbarena kapija, drvena crkva i crveno-crni vez krstićima. PDF za popunjavanje i štampu, 5×7 i A5, 7 jezika.","colors":"Crveno i crno na krem podlozi; Tamna varijanta sa zlatnim detaljima"},"bg":{"name":"Марамуреш","title":"Сватбена покана Марамуреш с румънски народни мотиви","tagline":"Марамурешката порта, дървената църква и червено-черният кръстат бод.","description":"Мотивите следват старите шевици по броене на нишки: ромбове, осемлъчни звезди, вълчи зъби и усуканото въже. Горе стои марамурешката порта със слънчевата розета или дървената църква с високата кула. Два варианта: червено и черно върху кремаво и тъмен, с ивици като на престилка и златни акценти.","metaTitle":"Румънска сватбена покана Марамуреш, PDF за попълване","metaDescription":"Традиционна румънска сватбена покана от Марамуреш: резбована порта, дървена църква и червено-черен кръстат бод. PDF за попълване и печат, 5×7 и A5, 7 езика.","colors":"Червено и черно върху кремаво; Тъмен вариант със златни акценти"},"tr":{"name":"Maramureș","title":"Romen halk motifli Maramureș düğün davetiyesi","tagline":"Maramureș kapısı, ahşap kilise ve kırmızı-siyah kanaviçe.","description":"Motifler eski sayma işlemelerini izler: eşkenar dörtgenler, sekiz köşeli yıldızlar, kurt dişleri ve burgulu ip. Üstte güneş rozetli Maramureș kapısı ya da yüksek kuleli ahşap kilise durur. İki seçenek: krem üzerine kırmızı ve siyah ile önlük şeritli, altın ayrıntılı koyu bir seçenek.","metaTitle":"Geleneksel Romen düğün davetiyesi Maramureș, doldurulabilir PDF","metaDescription":"Maramureș’ten geleneksel Romen düğün davetiyesi: oymalı kapı, ahşap kilise ve kırmızı-siyah kanaviçe. Doldurulabilir ve baskı PDF’i, 5×7 ve A5, 7 dil.","colors":"Krem üzerine kırmızı ve siyah; Altın ayrıntılı koyu seçenek"}}
